package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import htsjdk.samtools.util.IntervalTree;
import org.jlinalg.genetics.SomaticCoding;
import org.jlinalg.genetics.SomaticCoding.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;
import static org.jlinalg.cli.DndscvWorkflowTransport.*;

/** Independent event accounting, coding consequences, complete N/L identities and model/table diagnostics.
 * Original optimizers, confidence limits and selection likelihoods are retained rather than refitted here.
 */
final class DndscvWorkflowAudit {
    private DndscvWorkflowAudit() { }
    record Reference(Gene gene,String protein,double[] exposure,long[] splicePositions){ }
    record Mapping(DndscvWorkflowInputs.Key event,String gene){ }
    static List<Reference> reference(Path home,DndscvWorkflowRequest.Request r,DndscvWorkflowInputs.Budget meter)throws IOException{
        var index=read(home.resolve("index.json"),r);long count=integer(index.get("genes"),1,r.maximumGenes());var out=new ArrayList<Reference>();var names=new HashSet<String>();long total=0;
        for(String part:strings(index.get("parts"),r.outputFiles())){require(!part.contains("/")&&!part.contains("\\"),"Invalid reference part name");for(Object raw:list(read(home.resolve(part),r).get("genes"))){var g=object(raw);String name=label(g.get("name")),chr=label(g.get("chromosome"));require(names.add(name),"Repeated original reference gene");var exons=new ArrayList<Interval>();for(Object value:list(g.get("exons"))){var pair=list(value);require(pair.size()==2,"Invalid original exon width");exons.add(new Interval(integer(pair.get(0),1,Integer.MAX_VALUE),integer(pair.get(1),1,Integer.MAX_VALUE)));}var ss=list(g.get("splice_positions"));long[] splice=new long[ss.size()];for(int i=0;i<ss.size();i++)splice[i]=integer(ss.get(i),1,Integer.MAX_VALUE);String cds=text(g.get("cds")),up=text(g.get("up")),down=text(g.get("down")),sp=text(g.get("splice")),su=text(g.get("splice_up")),sd=text(g.get("splice_down"));total+=cds.length()+(long)sp.length();require(total<=r.referenceBases(),"Complete reference exceeds maximum_reference_bases");meter.add(cds.length()+(long)sp.length());Gene gene;try{gene=new Gene(name,chr,(int)integer(g.get("strand"),-1,1),exons,cds,up,down,splice,sp,su,sd);}catch(IllegalArgumentException|ArithmeticException failure){throw new IOException("Invalid original reference structure for "+name,failure);}out.add(new Reference(gene,g.get("protein")==null?"":text(g.get("protein")),new double[768],splice.clone()));}}
        require(out.size()==count&&total==integer(index.get("bases"),0,r.referenceBases()),"Incomplete original reference population");return List.copyOf(out);
    }
    static List<Reference> constructed(Path worker,DndscvWorkflowInputs.Population input,DndscvWorkflowRequest.Request r,DndscvWorkflowInputs.Budget meter)throws IOException{
        Table actual=table(worker.resolve("constructed-mutations.json"),r,meter);require(actual.rows()==input.events().size(),"Constructed event population differs");for(int i=0;i<actual.rows();i++){var k=input.events().get(i).key();require(actual.cell(i,"sampleID").equals(k.sample())&&actual.cell(i,"chr").equals(k.chromosome())&&number(actual,i,"pos")==k.position()&&actual.cell(i,"ref").equals(k.reference())&&actual.cell(i,"mut").equals(k.alternate()),"Constructed source mutation differs from captured input at row"+(i+1));}
        var selection=read(worker.resolve("reference-selection.json"),r);var all=strings(selection.get("all_reference_genes"),200000);var selected=strings(selection.get("selected_genes"),r.maximumGenes());var desired=new LinkedHashSet<>(input.requestedGenes().isEmpty()?all:input.requestedGenes());if(desired.contains("CDKN2A")&&r.reference().get("kind").equals("builtin")){require(r.genes().get("cdkn2a_policy").equals("source-expand-isoforms"),"Undeclared source gene alias");desired.remove("CDKN2A");desired.add("CDKN2A.p14arf");desired.add("CDKN2A.p16INK4a");}require(new HashSet<>(all).containsAll(desired)&&all.stream().filter(desired::contains).toList().equals(selected),"Original selected gene universe differs");List<Reference> refs=reference(worker.resolve("reference-input"),r,meter);require(refs.stream().map(g->g.gene().name()).toList().equals(selected),"Original reference gene order differs");require((long)refs.size()*768<=r.matrixEntries(),"Complete reference opportunity matrix exceeds capacity");
        try(var values=doubles(worker.resolve("reference-input-L.f64be.gz"),r)){for(Reference ref:refs){long[][] independent=null;if(r.reference().get("opportunities").equals("verify-unweighted-standard-code")){try{independent=ref.gene().opportunities().counts();}catch(IllegalArgumentException failure){throw new IOException("Native unweighted opportunity domain differs for "+ref.gene().name(),failure);}meter.add(3L*ref.gene().cds().length());}for(int c=0;c<4;c++)for(int row=0;row<192;row++){double value=values.readDouble();require(Double.isFinite(value)&&value>=0,"Invalid original opportunity value");ref.exposure()[c*192+row]=value;if(independent!=null)require(value==independent[row][c],"Original/native unweighted opportunity differs: "+ref.gene().name()+" channel"+row+" class"+c);}}require(values.read()==-1,"Extra original reference array values");}
        for(var numeric:Arrays.asList(input.covariates(),input.duplex()))if(numeric!=null)require(numeric.genes().equals(selected),"Supplied numeric genes must match the complete original selected gene order");for(var set:input.geneSets().entrySet())require(selected.containsAll(set.getValue()),"Gene-set member absent from selected reference: "+set.getKey());return refs;
    }
    static Map<String,Object> analysis(Path home,Map<String,Object> options,List<Reference> references,DndscvWorkflowInputs.Population input,DndscvWorkflowRequest.Request r,DndscvWorkflowInputs.Budget meter)throws IOException{
        var source=read(home.resolve("source-status.json"),r);require(bool(source.get("returned"))&&integer(source.get("seed"),0,2147483647)==integer(options.get("seed"),0,2147483647),"Original case failed or changed its declared seed");require(strings(source.get("RNG"),3).equals(List.of("Mersenne-Twister","Inversion","Rejection")),"Original RNG profile differs");var axes=read(home.resolve("matrix-axes.json"),r);var genes=strings(axes.get("gene_axis"),r.maximumGenes());var dim=list(axes.get("dim"));require(dim.size()==3&&integer(dim.get(0),192,192)==192&&integer(dim.get(1),4,4)==4&&integer(dim.get(2),1,r.maximumGenes())==genes.size(),"Original N/L dimensions differ");require((long)genes.size()*1536<=r.matrixEntries()&&new HashSet<>(genes).size()==genes.size(),"Complete N/L family exceeds capacity or repeats genes");meter.add((long)genes.size()*1536);var by=new LinkedHashMap<String,Reference>();for(Reference ref:references)by.put(ref.gene().name(),ref);require(by.keySet().containsAll(genes),"Original result introduced a reference gene");var finalNames=new HashSet<>(genes);var referenceOrder=new HashMap<String,Integer>();for(int i=0;i<references.size();i++){Reference ref=references.get(i);referenceOrder.put(ref.gene().name(),i);if(!finalNames.contains(ref.gene().name()))require(r.duplex().get("kind").equals("per-site")||Arrays.stream(ref.exposure()).sum()==0,"Original result dropped a positive-opportunity gene");}var outputReference=reference(home.resolve("reference-result"),r,meter);require(outputReference.stream().map(g->g.gene().name()).toList().equals(genes),"Returned reference/array gene axes differ");for(int i=0;i<genes.size();i++){Gene old=by.get(genes.get(i)).gene(),next=outputReference.get(i).gene();require(old.chromosome().equals(next.chromosome())&&old.strand()==next.strand()&&old.exons().equals(next.exons())&&old.cds().equals(next.cds()),"Source changed immutable coding reference structure");}
        var index=new HashMap<String,IntervalTree<Set<String>>>();for(String name:genes){Gene gene=by.get(name).gene();var tree=index.computeIfAbsent(gene.chromosome(),key->new IntervalTree<>());for(Interval exon:gene.exons())put(tree,(int)exon.start(),(int)exon.end(),name);for(long pos:by.get(name).splicePositions()){int p=Math.toIntExact(pos);put(tree,p,p,name);}}
        var mapped=new LinkedHashSet<Mapping>();var first=new HashSet<DndscvWorkflowInputs.Key>();var noOverlap=new HashSet<DndscvWorkflowInputs.Key>();for(var event:input.events()){var key=event.key();if(key.reference().equals(key.alternate())||!first.add(key))continue;meter.add(1);var tree=index.get(key.chromosome());int start=key.position()+(key.reference().charAt(0)==key.alternate().charAt(0)&&key.reference().length()>key.alternate().length()?1:0),end=key.position()+key.reference().length()-1;var hit=new LinkedHashSet<String>();if(tree!=null)for(var iter=tree.overlappers(start,end);iter.hasNext();)hit.addAll(iter.next().getValue());meter.add(hit.size());if(hit.isEmpty())noOverlap.add(key);for(String gene:hit)mapped.add(new Mapping(key,gene));}
        var sampleCounts=new HashMap<String,Integer>();for(Mapping m:mapped)sampleCounts.merge(m.event().sample(),1,Integer::sum);double maxSample=limit(options.get("max_coding_muts_per_sample")),maxGene=limit(options.get("max_muts_per_gene_per_sample"));var excludedSamples=new HashSet<String>();for(var e:sampleCounts.entrySet())if(e.getValue()>maxSample)excludedSamples.add(e.getKey());Table sampleTable=table(home.resolve("excluded-samples.json"),r,meter);require(new HashSet<>(sampleTable.strings("sample_id")).equals(excludedSamples),"Original sample exclusions differ from complete mapped event counts");
        var groups=new HashMap<List<String>,List<Mapping>>();for(Mapping m:mapped)if(!excludedSamples.contains(m.event().sample()))groups.computeIfAbsent(List.of(m.event().sample(),m.gene()),k->new ArrayList<>()).add(m);var excluded=new HashSet<Mapping>();for(var group:groups.values()){group.sort(Comparator.comparingInt(m->m.event().position()));int from=0;while(from<group.size()){int to=from+1;while(to<group.size()&&group.get(to).event().position()==group.get(from).event().position())to++;double averageRank=((from+1)+(double)to)/2;if(averageRank>maxGene)excluded.addAll(group.subList(from,to));from=to;}}
        Path excludedPath=home.resolve("exclmuts.json");if(Files.exists(excludedPath))require(mappings(table(excludedPath,r,meter)).equals(excluded),"Original per-gene/sample exclusions differ, including average-rank ties");else require(excluded.isEmpty(),"Original omitted excluded-event table");var expected=new LinkedHashMap<Mapping,Annotation>();var wrong=new HashMap<DndscvWorkflowInputs.Key,Integer>();var counts=new HashMap<String,long[]>();int nonSnv=0,stopLoss=0;
        for(Mapping m:mapped){if(excludedSamples.contains(m.event().sample())||excluded.contains(m))continue;var key=m.event();boolean snv=key.reference().length()==1&&key.alternate().length()==1&&key.reference().charAt(0)!='-'&&key.alternate().charAt(0)!='-';if(!snv){expected.put(m,null);nonSnv++;continue;}Annotation annotation;try{annotation=by.get(m.gene()).gene().annotate(key.chromosome(),key.position(),key.reference().charAt(0),key.alternate().charAt(0));}catch(IllegalArgumentException e){throw new IOException("Original/native coding annotation domain differs: "+m,e);}if(annotation.wrongReference()){wrong.merge(key,1,Integer::sum);continue;}require(annotation.channel()>=0,"Original returned mutation with unresolved native context");expected.put(m,annotation);if(annotation.impact()==Impact.STOP_LOSS)stopLoss++;else counts.computeIfAbsent(m.gene(),k->new long[768])[annotation.impact().column()*192+annotation.channel()]++;}
        Table annot=table(home.resolve("annotmuts.json"),r,meter);var seen=new HashSet<Mapping>();for(int i=0;i<annot.rows();i++){var mapping=new Mapping(key(annot,i),annot.cell(i,"gene"));require(expected.containsKey(mapping)&&seen.add(mapping),"Unexpected/repeated original annotated event");Annotation a=expected.get(mapping);require(annot.cell(i,"pid").equals(by.get(mapping.gene()).protein()),"Original protein identifier differs");if(a==null)require(annot.cell(i,"impact").equals("no-SNV"),"Original complex event was reclassified");else{require(annot.cell(i,"impact").equals(a.impact().label())&&annot.cell(i,"ref_cod").equals(""+a.referenceCoding())&&annot.cell(i,"mut_cod").equals(""+a.alternateCoding())&&annot.cell(i,"ref3_cod").equals(a.referenceContext())&&annot.cell(i,"mut3_cod").equals(a.alternateContext())&&annot.cell(i,"codonsub").equals(a.codonChange())&&annot.cell(i,"ntchange").equals(a.nucleotideChange())&&annot.cell(i,"aachange").equals(a.aminoAcidChange()),"Original/native complete coding annotation differs: "+mapping);}}
        require(seen.equals(expected.keySet()),"Original annotation population incomplete");Path wrongPath=home.resolve("wrongmuts.json");var actualWrong=new HashMap<DndscvWorkflowInputs.Key,Integer>();if(Files.exists(wrongPath)){Table table=table(wrongPath,r,meter);for(int i=0;i<table.rows();i++)actualWrong.merge(key(table,i),1,Integer::sum);}require(actualWrong.equals(wrong),"Original wrong-reference dispositions differ");
        Table genemuts=table(home.resolve("genemuts.json"),r,meter);require(genemuts.strings("gene_name").equals(genes),"Original genemuts/array axes differ");var mle=table(home.resolve("mle_submodel.json"),r,meter);var parameters=new HashMap<String,Double>();for(int i=0;i<mle.rows();i++)require(parameters.put(mle.cell(i,"name"),number(mle,i,"mle"))==null,"Repeated original model parameter");var substitution=read(home.resolve("substitution-model.json"),r);var equations=strings(substitution.get("expressions"),768);require(equations.size()==768,"Incomplete original substitution model");double[] rates=new double[192];for(int row=0;row<192;row++){double rate=1;for(String name:equations.get(row).split("\\*",-1)){require(parameters.containsKey(name),"Missing original rate parameter");rate*=parameters.get(name);}require(Double.isFinite(rate)&&rate>=0,"Nonfinite original substitution rate");rates[row]=rate;}
        double[][] total=new double[2][768];long counted=0;try(var ns=doubles(home.resolve("N.f64be.gz"),r);var ls=doubles(home.resolve("L.f64be.gz"),r)){for(int g=0;g<genes.size();g++){String name=genes.get(g);long[] independent=counts.get(name);double[] observed=new double[4],expectation=new double[4];int inputIndex=referenceOrder.get(name);double weight=input.duplex()==null?1:input.duplex().values().get(inputIndex).get(0);for(int c=0;c<4;c++)for(int row=0;row<192;row++){int slot=c*192+row;double n=ns.readDouble(),l=ls.readDouble();require(Double.isFinite(n)&&n>=0&&n==Math.rint(n)&&n==(independent==null?0:independent[slot]),"Complete original/native N matrix differs: "+name+":"+slot);require(Double.isFinite(l)&&l>=0,"Invalid original L matrix");if(!r.duplex().get("kind").equals("per-site"))require(l==by.get(name).exposure()[slot]*weight,"Original L differs from explicit supplied opportunity/coverage: "+name+":"+slot);observed[c]+=n;expectation[c]+=l*rates[row];total[0][slot]+=n;total[1][slot]+=l;counted+=(long)n;}for(int c=0;c<4;c++){String suffix=List.of("syn","mis","non","spl").get(c);require(number(genemuts,g,"n_"+suffix)==observed[c],"Original gene count differs from complete N");near(number(genemuts,g,"exp_"+suffix),expectation[c],"Original expected count differs from L and source rates");}}require(ns.read()==-1&&ls.read()==-1,"Extra original N/L entries");}
        auditPoisson(home,total,r,meter);int families=0,nonfinite=0;for(String name:List.of("globaldnds","sel_cv","sel_loc","geneindels","syncv")){Path path=home.resolve(name+".json");if(!Files.exists(path))continue;Table table=table(path,r,meter);families+=bh(table);for(var row:table.kinds())for(String k:row)if(!k.equals("value"))nonfinite++;}
        if(bool(options.get("gene_set_comparison"))){Object raw=NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(home.resolve("gene-sets/index.json"),r.jsonBytes())),r.jsonBytes(),r.jsonNodes());var sets=list(raw);require(sets.size()==input.geneSets().size(),"Original gene-set family differs");var setNames=new ArrayList<>(input.geneSets().keySet());for(int i=0;i<sets.size();i++){var set=object(sets.get(i));String name=text(set.get("id")),directory=text(set.get("directory"));require(name.equals(setNames.get(i))&&strings(set.get("genes"),r.maximumGenes()).equals(input.geneSets().get(name))&&directory.equals(String.format(Locale.ROOT,"set-%06d",i+1)),"Original gene-set membership/order differs");for(String label:List.of("globaldnds_geneset","globaldnds_rest"))table(home.resolve("gene-sets").resolve(directory).resolve(label+".json"),r,meter);}}
        // Every emitted table is checked, including diagnostic models and optional families.
        try(var paths=Files.walk(home)){for(Path path:paths.filter(p->p.getFileName().toString().endsWith(".json")).toList()){Object raw=NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(path,r.jsonBytes())),r.jsonBytes(),r.jsonNodes());if(raw instanceof Map<?,?> m&&m.containsKey("column_names")&&m.containsKey("parts")&&m.containsKey("rows"))table(path,r,meter);}}
        writeLedger(home.resolve("native-event-ledger.tsv"),input,mapped,noOverlap,excludedSamples,excluded,wrong,expected,r.outputBytes());
        var report=new LinkedHashMap<String,Object>();report.put("id",options.get("id"));report.put("input_events",input.events().size());report.put("duplicate_input_rows_retained",input.duplicateOf().size());report.put("reference_genes",genes.size());report.put("annotated_gene_events",annot.rows());report.put("counted_substitutions",counted);report.put("complex_gene_events",nonSnv);report.put("stop_loss_events_retained_not_counted",stopLoss);report.put("wrong_reference_gene_events",wrong.values().stream().mapToInt(Integer::intValue).sum());report.put("BH_families_checked",families);report.put("nonfinite_original_metadata_fields_retained",nonfinite);report.put("original_optimizers_or_selection_likelihoods_independently_refitted",false);report.put("site_coverage_independently_recomputed",false);return report;
    }
    private static void put(IntervalTree<Set<String>> tree,int start,int end,String name){var value=new LinkedHashSet<String>();value.add(name);Set<String> old=tree.put(start,end,value);if(old!=null){value.addAll(old);tree.put(start,end,value);}}
    private static DndscvWorkflowInputs.Key key(Table t,int row)throws IOException{double p=number(t,row,"pos");require(p>=1&&p<=Integer.MAX_VALUE&&p==Math.rint(p),"Original event position changed");return new DndscvWorkflowInputs.Key(t.cell(row,"sampleID"),t.cell(row,"chr"),(int)p,t.cell(row,"ref"),t.cell(row,"mut"));}
    private static Set<Mapping> mappings(Table t)throws IOException{var out=new HashSet<Mapping>();for(int i=0;i<t.rows();i++)require(out.add(new Mapping(key(t,i),t.cell(i,"gene"))),"Repeated original excluded mapping");return out;}
    private static double limit(Object value)throws IOException{return value instanceof String?Double.POSITIVE_INFINITY:finite(value,0,20000000);}
    private static void near(double actual,double expected,String detail)throws IOException{require(Double.isFinite(actual)&&Double.isFinite(expected)&&Math.abs(actual-expected)<=Math.max(64*Math.ulp(Math.max(Math.abs(actual),Math.abs(expected))),3e-12*Math.max(Math.abs(actual),Math.abs(expected))),detail);}
    private static int bh(Table table)throws IOException{int families=0;for(String p:table.columns())if(p.startsWith("p")&&table.columns().contains("q"+p.substring(1))){String q="q"+p.substring(1);var indices=new ArrayList<Integer>();for(int i=0;i<table.rows();i++){if(table.kind(i,p).equals("value")){double x=number(table,i,p);require(x>=0&&x<=1,"Invalid source probability");indices.add(i);}else require(table.kind(i,p).equals(table.kind(i,q)),"Original missing P/q kind changed");}indices.sort(Comparator.comparingDouble(i->{try{return number(table,i,p);}catch(IOException e){throw new UncheckedIOException(e);}}));double next=1;for(int rank=indices.size();rank>=1;rank--){int i=indices.get(rank-1);next=Math.min(next,(double)indices.size()/rank*number(table,i,p));near(number(table,i,q),next,"Original BH identity differs: "+q);}families++;}return families;}
    private static void auditPoisson(Path home,double[][] aggregate,DndscvWorkflowRequest.Request r,DndscvWorkflowInputs.Budget meter)throws IOException{Table rows=table(home.resolve("poisson-model-rows.json"),r,meter);int expected=0;for(int slot=0;slot<768;slot++)if(aggregate[1][slot]!=0){require(expected<rows.rows()&&number(rows,expected,"response")==aggregate[0][slot],"Original Poisson response differs from complete N");near(number(rows,expected,"offset"),Math.log(aggregate[1][slot]),"Original Poisson offset differs from complete L");near(number(rows,expected,"fitted"),Math.exp(number(rows,expected,"linear_predictor")),"Original Poisson inverse-link identity differs");expected++;}require(expected==rows.rows(),"Incomplete original Poisson rows");}
    private static void writeLedger(Path path,DndscvWorkflowInputs.Population input,Set<Mapping> mapped,Set<DndscvWorkflowInputs.Key> noOverlap,Set<String> excludedSamples,Set<Mapping> excluded,Map<DndscvWorkflowInputs.Key,Integer> wrong,Map<Mapping,Annotation> expected,long maximumBytes)throws IOException{
        var by=new HashMap<DndscvWorkflowInputs.Key,List<Mapping>>();for(Mapping m:mapped)by.computeIfAbsent(m.event(),k->new ArrayList<>()).add(m);try(Writer out=new FilterWriter(Files.newBufferedWriter(path,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){private long written;@Override public void write(String value,int offset,int length)throws IOException{long bytes=value.substring(offset,offset+length).getBytes(StandardCharsets.UTF_8).length;require(bytes<=maximumBytes-written,"Native ledger exceeds maximum_output_bytes");super.write(value,offset,length);written+=bytes;}}){out.write("input_row\tsample_id\tchromosome\tposition\treference\talternate\tgene_id\tdisposition\n");for(var event:input.events()){var key=event.key();String common=event.row()+"\t"+key.sample()+"\t"+key.chromosome()+"\t"+key.position()+"\t"+key.reference()+"\t"+key.alternate()+"\t";if(input.duplicateOf().containsKey(event.row()))out.write(common+".\tsource-exact-duplicate-collapse-of-row"+input.duplicateOf().get(event.row())+"\n");else if(key.reference().equals(key.alternate()))out.write(common+".\tsource-identical-reference-alternate-omitted\n");else if(noOverlap.contains(key))out.write(common+".\tno-selected-reference-overlap\n");else for(Mapping m:by.getOrDefault(key,List.of())){String disposition=excludedSamples.contains(key.sample())?"source-excluded-sample":excluded.contains(m)?"source-per-gene-sample-average-rank-excluded":!expected.containsKey(m)?"source-wrong-reference-excluded":expected.get(m)==null?"source-complex-event-indel-family":expected.get(m).impact()==Impact.STOP_LOSS?"source-stop-loss-retained-outside-N":"source-counted-"+expected.get(m).impact().label();out.write(common+m.gene()+"\t"+disposition+"\n");}}}
    }
}
